<?php get_header();while(have_posts()):the_post();$id=get_the_ID(); ?><article class="wrap section"><div class="breadcrumb"><a href="<?php echo esc_url(bcst_home()); ?>"><?php echo esc_html(bcst_t('Home')); ?></a> / <a href="<?php echo esc_url(get_post_type_archive_link('bcst_product')); ?>"><?php echo esc_html(bcst_t('Products')); ?></a> / <?php the_title(); ?></div><div class="split"><div class="content"><p class="eyebrow"><?php echo esc_html(bcst_t('Product information')); ?></p><h1><?php the_title(); ?></h1><p><?php echo esc_html(get_post_meta($id,'_bcst_model',true)); ?></p><?php if(has_post_thumbnail())the_post_thumbnail('large');else{echo '<div class="placeholder">';bcst_symbol();echo '</div>';} ?><div class="gallery"><?php foreach(array_filter(array_map('absint',explode(',',get_post_meta($id,'_bcst_gallery',true)))) as $image)echo wp_get_attachment_image($image,'medium'); ?></div><?php the_content();$specs=get_post_meta($id,'_bcst_specs',true);if($specs): ?><h2><?php echo esc_html(bcst_t('Product specifications')); ?></h2><table><tbody><?php foreach(explode("\n",$specs) as $line){$pair=explode('|',$line,2);if(count($pair)===2)echo '<tr><th scope="row">'.esc_html(trim($pair[0])).'</th><td>'.esc_html(trim($pair[1])).'</td></tr>';} ?></tbody></table><?php endif;$download=get_post_meta($id,'_bcst_download',true);if($download)echo '<p><a class="button secondary" href="'.esc_url($download).'">'.esc_html(bcst_t('Downloads')).' ↓</a></p>';$video=get_post_meta($id,'_bcst_video',true);if($video)echo wp_oembed_get($video)?:'<a href="'.esc_url($video).'">'.esc_html(bcst_t('Video')).'</a>';$faq=get_post_meta($id,'_bcst_faq',true);if($faq){echo '<h2>'.esc_html(bcst_t('Frequently asked questions')).'</h2>';foreach(explode("\n",$faq) as $line){$pair=explode('|',$line,2);if(count($pair)===2)echo '<details><summary>'.esc_html($pair[0]).'</summary><p>'.esc_html($pair[1]).'</p></details>';}} ?></div><aside><?php echo shortcode_exists('bcst_inquiry')?do_shortcode('[bcst_inquiry]'):''; ?></aside></div>
<?php $related=array_filter(array_map('absint',explode(',',get_post_meta($id,'_bcst_related',true))));if($related){$q=new WP_Query(array('post_type'=>'bcst_product','post__in'=>$related,'post__not_in'=>array($id),'posts_per_page'=>3));if($q->have_posts()){echo '<h2>'.esc_html(bcst_t('Related products')).'</h2><div class="grid">';while($q->have_posts()){$q->the_post();bcst_card();}echo '</div>';}wp_reset_postdata();} ?></article><?php endwhile;get_footer(); ?>
